UPDATE accommodations
SET status = #{status}, updated_at = NOW()
WHERE accommodation_id = #{accommodationId}

mapper.select:
SELECT
    COUNT(*)
FROM accommodations a
LEFT JOIN users u ON a.host_id = u.user_id

    a.accommodation_id IS NOT NULL



        AND a.sido_code = #{sidoCode}


        AND a.gugun_code = #{gugunCode}


        AND a.status = #{status}




        AND a.accommodation_type = #{accommodationType}




        AND (a.title LIKE CONCAT('%', #{keyword}, '%')
        OR a.description LIKE CONCAT('%', #{keyword}, '%')
        OR a.address LIKE CONCAT('%', #{keyword}, '%'))




        AND EXISTS (
        SELECT 1 FROM rooms r
        WHERE r.accommodation_id = a.accommodation_id

            AND r.price BETWEEN #{minPrice} AND #{maxPrice}


            AND r.price >= #{minPrice}


            AND r.price <= #{maxPrice}

        )




        AND EXISTS (
        SELECT 1
        FROM rooms r
        WHERE r.accommodation_id = a.accommodation_id
        AND r.capacity >= #{guestCount}
        )

SELECT a.*, u.username AS host_name FROM accommodations a LEFT JOIN users u ON a.host_id = u.user_id
a.accommodation_id IS NOT NULL
AND a.sido_code = #{sidoCode}
AND a.gugun_code = #{gugunCode}
AND a.status = #{status}
AND a.accommodation_type = #{accommodationType}
AND (a.title LIKE CONCAT('%', #{keyword}, '%') OR a.description LIKE CONCAT('%', #{keyword}, '%') OR a.address LIKE CONCAT('%', #{keyword}, '%'))
AND EXISTS ( SELECT 1 FROM rooms r WHERE r.accommodation_id = a.accommodation_id
AND r.price BETWEEN #{minPrice} AND #{maxPrice}
AND r.price >= #{minPrice}
AND r.price <= #{maxPrice}
)
AND EXISTS ( SELECT 1 FROM rooms r WHERE r.accommodation_id = a.accommodation_id AND r.capacity >= #{guestCount} )
ORDER BY
a.recommend_score DESC, a.created_at DESC a.review_count DESC, a.recommend_score DESC, a.created_at DESC a.review_count ASC, a.recommend_score DESC, a.created_at DESC a.min_room_price ASC, a.recommend_score DESC, a.created_at DESC a.max_room_price DESC, a.recommend_score DESC, a.created_at DESC a.title ASC, a.recommend_score DESC, a.created_at DESC a.created_at DESC a.created_at DESC
ORDER BY a.recommend_score DESC, a.created_at DESC
LIMIT #{limit} OFFSET #{offset}
